<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three Biome Islands</title>
<style>
  html, body { margin: 0; padding: 0; overflow: hidden; background: #0b1a2a; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ---------- Renderer ----------
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
document.body.appendChild(renderer.domElement);

// ---------- Scene ----------
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9fd3e8);
scene.fog = new THREE.Fog(0x9fd3e8, 45, 130);

// ---------- Camera ----------
const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 18, 42);

// ---------- Lights ----------
const hemi = new THREE.HemisphereLight(0xbfe3ff, 0x3a4a2a, 0.75);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xfff2d6, 1.35);
sun.position.set(30, 45, 20);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 160;
sun.shadow.camera.left = -45;
sun.shadow.camera.right = 45;
sun.shadow.camera.top = 45;
sun.shadow.camera.bottom = -45;
sun.shadow.bias = -0.0004;
scene.add(sun);

// ---------- Water ----------
const water = new THREE.Mesh(
  new THREE.PlaneGeometry(400, 400),
  new THREE.MeshStandardMaterial({ color: 0x1f6f9c, roughness: 0.25, metalness: 0.15 })
);
water.rotation.x = -Math.PI / 2;
water.position.y = 0;
scene.add(water);

// ---------- Helpers ----------
function makeIsland(radius, height, color) {
  const geo = new THREE.CylinderGeometry(radius * 0.55, radius, height, 40, 1);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const r = Math.hypot(x, z);
    if (r > 0.001) {
      const a = Math.atan2(z, x);
      const n = Math.sin(a * 5) * 0.06 + Math.cos(a * 3 + 1.3) * 0.05;
      const f = 1 + n * (y / height);
      pos.setX(i, x * f);
      pos.setZ(i, z * f);
    }
  }
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color, roughness: 0.95, flatShading: true }));
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function makeRock(color) {
  const g = new THREE.DodecahedronGeometry(1, 0);
  const m = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ color, roughness: 1, flatShading: true }));
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function makeCactus() {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: 0x4f8a3d, roughness: 0.8 });
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.26, 1.6, 10), mat);
  body.position.y = 0.8;
  body.castShadow = true;
  g.add(body);
  const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.16, 0.8, 8), mat);
  arm.position.set(0.35, 1.0, 0);
  arm.rotation.z = -0.7;
  arm.castShadow = true;
  g.add(arm);
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.24, 10, 8), mat);
  cap.position.y = 1.6;
  cap.castShadow = true;
  g.add(cap);
  return g;
}

function makePalm() {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(
    new THREE.CylinderGeometry(0.12, 0.2, 2.2, 8),
    new THREE.MeshStandardMaterial({ color: 0x8a5a2b, roughness: 1 })
  );
  trunk.position.y = 1.1;
  trunk.castShadow = true;
  g.add(trunk);
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f8f3a, roughness: 0.8, side: THREE.DoubleSide });
