renderer.toneMappingExposure = 1.15;
app.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x04060d, 0.0016);

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 4000);
camera.position.set(0, 46, 118);

window.SCENE = scene;
window.CAMERA = camera;
window.RENDERER = renderer;

/* ---------- procedural textures (no external assets) ---------- */
function canvasTex(size, draw){
  const c = document.createElement('canvas'); c.width=c.height=size;
  draw(c.getContext('2d'), size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
function glowTex(){
  return canvasTex(256,(ctx,s)=>{
    const g = ctx.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
    g.addColorStop(0,'rgba(255,240,200,1)');
    g.addColorStop(0.25,'rgba(255,190,90,0.55)');
    g.addColorStop(0.6,'rgba(255,140,40,0.12)');
    g.addColorStop(1,'rgba(255,120,20,0)');
    ctx.fillStyle=g; ctx.fillRect(0,0,s,s);
  });
}
function planetTex(base, band, spots){
  return canvasTex(512,(ctx,s)=>{
    const g = ctx.createLinearGradient(0,0,0,s);
    g.addColorStop(0,base[0]); g.addColorStop(.5,base[1]); g.addColorStop(1,base[2]);
    ctx.fillStyle=g; ctx.fillRect(0,0,s,s);
    // horizontal bands
    for(let i=0;i<band.count;i++){
      const y = Math.random()*s, h = 4+Math.random()*band.thick;
      ctx.globalAlpha = band.alpha*(0.4+Math.random()*0.6);
      ctx.fillStyle = band.col;
      ctx.fillRect(0,y,s,h);
    }
    // spots / storms
    ctx.globalAlpha = 1;
    for(let i=0;i<spots;i++){
      const x=Math.random()*s, y=Math.random()*s, r=3+Math.random()*14;
      ctx.globalAlpha = 0.15+Math.random()*0.3;
      ctx.fillStyle = spotsCol;
      ctx.beginPath(); ctx.arc(x,y,r,0,7); ctx.fill();
    }
    ctx.globalAlpha=1;
  });
