let spotsCol='#000';

/* ---------- starfield (200+ points) ---------- */
function makeStars(count, size, spread, color){
  const pos = new Float32Array(count*3);
  for(let i=0;i<count;i++){
    const r = spread*(0.4+Math.random()*0.6);
    const t = Math.random()*Math.PI*2;
    const p = Math.acos(2*Math.random()-1);
    pos[i*3]   = r*Math.sin(p)*Math.cos(t);
    pos[i*3+1] = r*Math.cos(p);
    pos[i*3+2] = r*Math.sin(p)*Math.sin(t);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos,3));
  const mat = new THREE.PointsMaterial({size, color, transparent:true,
    depthWrite:false, blending:THREE.AdditiveBlending, sizeAttenuation:true});
  return new THREE.Points(geo, mat);
}
const stars1 = makeStars(1400, 1.4, 900, 0xffffff);
const stars2 = makeStars(500, 2.6, 1100, 0x9fc4ff);
const stars3 = makeStars(300, 2.2, 1000, 0xffd9a0);
