   desc:'A blue marble of oceans and drifting clouds, home to the moon Luna.'},
  {name:'Ares', color:0xd1663a, radius:1.9, orbit:52, speed:0.55,
   base:['#a8431f','#e07a44','#8a3418'], band:{count:8,col:'#f0a06a',thick:6,alpha:.35}, spots:8,
   desc:'A rust-red desert world with polar ice caps and a thin, cold atmosphere.'}
];

const orbitLines = [];
const planetObjs = [];
const pickables = [];

function makeOrbit(radius, color){
  const pts=[];
  for(let i=0;i<=128;i++){
    const a=i/128*Math.PI*2;
    pts.push(new THREE.Vector3(Math.cos(a)*radius,0,Math.sin(a)*radius));
  }
  const geo=new THREE.BufferGeometry().setFromPoints(pts);
  const mat=new THREE.LineBasicMaterial({color, transparent:true, opacity:0.28});
  const line=new THREE.Line(geo,mat);
  scene.add(line); orbitLines.push(line);
  return line;
}

PLANETS.forEach((p,idx)=>{
  spotsCol = p.spots>0 ? (p.name==='Ceres'?'#eaf4ff':'#5a2410') : '#000';
  const tex = planetTex(p.base, p.band, p.spots);
  const mat = new THREE.MeshStandardMaterial({map:tex, roughness:0.85, metalness:0.05});
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(p.radius,40,40), mat);

  const pivot = new THREE.Object3D();
  pivot.rotation.y = Math.random()*Math.PI*2;
