    depthWrite:false, opacity:0.22 }));
  rim.scale.set(p.radius*4.2,p.radius*4.2,1);
  mesh.add(rim);

  makeOrbit(p.orbit, p.color);

  const obj = {name:p.name, mesh, pivot, speed:p.speed, radius:p.radius,
    spin:0.3+Math.random()*0.5, color:p.color, desc:p.desc, orbit:p.orbit, idx};
  planetObjs.push(obj);
  pickables.push(mesh);
  mesh.userData.body = obj;
});

/* ---------- moon orbiting the third planet (Ceres) ---------- */
const ceres = planetObjs[2];
const moonPivot = new THREE.Object3D();
ceres.mesh.add(moonPivot);
