addLabel(moonObj, '#c9cdd6', 1.4);
const sunLabel = labelSprite('SOL','#ffd27a'); sunLabel.position.y=9; sunGroup.add(sunLabel);
sunLabel.visible=false; labels.push(sunLabel);

/* ---------- interaction: orbit controls (custom) ---------- */
const ctrl = {
  target:new THREE.Vector3(0,0,0),
  theta:0.5, phi:1.15, radius:118,
  minR:12, maxR:320,
  dragging:false, px:0, py:0,
  autoRotate:true
};
function applyCam(){
  const {theta,phi,radius,target}=ctrl;
  camera.position.set(
    target.x + radius*Math.sin(phi)*Math.cos(theta),
    target.y + radius*Math.cos(phi),
    target.z + radius*Math.sin(phi)*Math.sin(theta)
  );
  camera.lookAt(target);
}
applyCam();

const dom = renderer.domElement;
dom.addEventListener('pointerdown',e=>{ctrl.dragging=true;ctrl.px=e.clientX;ctrl.py=e.clientY;});
addEventListener('pointerup',()=>ctrl.dragging=false);
addEventListener('pointermove',e=>{
  if(!ctrl.dragging) return;
  const dx=e.clientX-ctrl.px, dy=e.clientY-ctrl.py;
  ctrl.px=e.clientX; ctrl.py=e.clientY;
  ctrl.theta -= dx*0.005;
  ctrl.phi   -= dy*0.005;
  ctrl.phi = Math.max(0.15, Math.min(Math.PI-0.15, ctrl.phi));
  ctrl.autoRotate=false;
});
dom.addEventListener('wheel',e=>{
  e.preventDefault();
  ctrl.radius *= (1 + Math.sign(e.deltaY)*0.08);
  ctrl.radius = Math.max(ctrl.minR, Math.min(ctrl.maxR, ctrl.radius));
  ctrl.autoRotate=false;
},{passive:false});

/* ---------- picking / focus ---------- */
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
let focusBody = null;
let downX=0, downY=0;
dom.addEventListener('pointerdown',e=>{downX=e.clientX;downY=e.clientY;});
dom.addEventListener('pointerup',e=>{
  if(Math.hypot(e.clientX-downX,e.clientY-downY)>6) return; // was a drag
  ndc.x=(e.clientX/innerWidth)*2-1;
  ndc.y=-(e.clientY/innerHeight)*2+1;
  ray.setFromCamera(ndc,camera);
  const hit=ray.intersectObjects(pickables,false)[0];
  if(hit) focusOn(hit.object.userData.body);
});

function focusOn(body){
  focusBody = body;
  document.querySelectorAll('.row').forEach(r=>r.classList.remove('active'));
  const row=document.querySelector(`.row[data-body="${body.name.toLowerCase()}"]`);
  if(row) row.classList.add('active');
  updateFocusCard(body);
}
function focusOnSun(){
  focusBody=null;
  document.querySelectorAll('.row').forEach(r=>r.classList.remove('active'));
  updateFocusCard({name:'The Sun', color:0xffd27a, radius:6, orbit:0,
