  fname.textContent = b.name;
  const cells=[
    ['Radius', b.radius.toFixed(1)+' R'],
    ['Orbit', b.orbit? b.orbit.toFixed(1)+' AU':'—'],
    ['Speed', b.speed? b.speed.toFixed(2)+'×':'—'],
    ['Class', b.name==='The Sun'?'Star':(b.name==='Luna'?'Moon':'Planet')]
  ];
  fgrid.innerHTML = cells.map(c=>`<div class="cell"><div class="k">${c[0]}</div><div class="v">${c[1]}</div></div>`).join('');
  fdesc.textContent = b.desc;
