  pauseBtn.classList.toggle('on',paused);});

/* ---------- animation ---------- */
const clock=new THREE.Clock();
let simTime=0, fpsAcc=0, fpsFrames=0, fpsTimer=0;
const simEl=document.getElementById('simtime'), fpsEl=document.getElementById('fps');

function animate(){
  requestAnimationFrame(animate);
  const dt=Math.min(clock.getDelta(),0.05);

  if(!paused){
    simTime += dt*timeScale;
    planetObjs.forEach(o=>{
      o.pivot.rotation.y += o.speed*dt*timeScale;
      o.mesh.rotation.y  += o.spin*dt*timeScale;
    });
    moonPivot.rotation.y += moonObj.speed*dt*timeScale;
    sun.rotation.y += 0.05*dt*timeScale;
  }

  // sun pulse
  const pulse = 1 + Math.sin(simTime*1.5)*0.04;
  corona.scale.set(34*pulse,34*pulse,1);
  corona2.scale.set(60*(2-pulse),60*(2-pulse),1);
  sunLight.intensity = 3.0 + Math.sin(simTime*2)*0.4;

  // star twinkle
  stars1.material.opacity = 0.85 + Math.sin(simTime*0.7)*0.1;
  stars2.material.opacity = 0.7 + Math.sin(simTime*1.1+1)*0.15;
  stars3.material.opacity = 0.6 + Math.sin(simTime*0.9+2)*0.15;
  stars1.rotation.y += dt*0.005;
  stars2.rotation.y -= dt*0.003;

  // camera follow / auto-rotate
  if(focusBody){
    const wp=new THREE.Vector3(); focusBody.mesh.getWorldPosition(wp);
    ctrl.target.lerp(wp, 0.08);
    ctrl.radius += (focusBody.radius*6 - ctrl.radius)*0.05;
  } else {
    ctrl.target.lerp(new THREE.Vector3(0,0,0),0.05);
    if(ctrl.autoRotate) ctrl.theta += dt*0.05;
  }
  applyCam();

  // fps + sim clock
  fpsAcc+=dt; fpsFrames++; fpsTimer+=dt;
  if(fpsTimer>=0.5){
    fpsEl.textContent=Math.round(fpsFrames/fpsAcc);
    fpsAcc=0;fpsFrames=0;fpsTimer=0;
  }
  const s=Math.floor(simTime);
  const hh=String(Math.floor(s/3600)).padStart(2,'0');
  const mm=String(Math.floor(s/60)%60).padStart(2,'0');
  const ss=String(s%60).padStart(2,'0');
  simEl.textContent=`T+${hh}:${mm}:${ss}`;

  renderer.render(scene,camera);
}
animate();

/* ---------- resize ---------- */
addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});

/* ---------- hide loader ---------- */
requestAnimationFrame(()=>setTimeout(()=>document.getElementById('loader').classList.add('hide'),400));
