  if(!paused){
    simTime += dt*timeScale;
    planetObjs.forEach(o=>{
      o.pivot.rotation.y += o.speed*dt*timeScale;
      o.mesh.rotation.y  += o.spin*dt*timeScale;
    });
    moonPivot.rotation.y += moonObj.speed*dt*timeScale;
    sun.rotation.y += 0.05*dt*timeScale;
  }

  // sun pulse
  const pulse = 1 + Math.sin(simTime*1.5)*0.04;
  corona.scale.set(34*pulse,34*pulse,1);
