    topColor:    { value: new THREE.Color(0x2f6fb0) },
    midColor:    { value: new THREE.Color(0x8fb4dd) },
    bottomColor: { value: new THREE.Color(0xf3d9b0) }
  },
  vertexShader: `
    varying vec3 vDir;
    void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
  fragmentShader: `
    uniform vec3 topColor; uniform vec3 midColor; uniform vec3 bottomColor;
    varying vec3 vDir;
    void main(){
      float h = clamp(vDir.y, -1.0, 1.0);
      vec3 col = mix(bottomColor, midColor, smoothstep(-0.15, 0.12, h));
      col = mix(col, topColor, smoothstep(0.12, 0.75, h));
      gl_FragColor = vec4(col, 1.0);
