  const rows = Math.max(2, Math.floor(h / 3.2));
  const winGeo = new THREE.PlaneGeometry(1.5, 1.9);
  const winMat = new THREE.MeshStandardMaterial({
    color: 0x11161f, roughness: 0.35, metalness: 0.1,
    emissive: winOn.clone(), emissiveIntensity: 0.0
  });
  const winMesh = new THREE.InstancedMesh(winGeo, winMat, cols * rows * 2);
