  const q = new THREE.Quaternion();
  const up = new THREE.Vector3(0, 1, 0);
  let idx = 0;
  for (const side of [1, -1]) {
    const n = new THREE.Vector3(0, 0, side);
    q.setFromUnitVectors(up, n);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
