        const py = (r + 0.5) * (h / rows);
        const pz = side * (d / 2 + 0.02);
        m.compose(new THREE.Vector3(px, py, pz), q, new THREE.Vector3(1, 1, 1));
        winMesh.setMatrixAt(idx++, m);
